  const rows=[...byId.values()].filter(r=>!blocked.has(r.feedback_id)).sort((a,b)=>a.feedback_id.localeCompare(b.feedback_id));
  return {demo:true,status:rejects.length?'partial':'ok',rows,rejects};
}
